     1	import type { Clock } from "../clock.ts";
     2	import { badRequest, conflict, notFound } from "../errors.ts";
     3	import type { Order, OrderRepository } from "../repositories/orderRepository.ts";
     4	
     5	export class OrderService {
     6	  constructor(
     7	    private readonly orders: OrderRepository,
     8	    private readonly clock: Clock,
     9	  ) {}
    10	
    11	  create(customer: unknown, amountCents: unknown): Order {
    12	    if (typeof customer !== "string" || customer.trim() === "") {
    13	      throw badRequest("INVALID_REQUEST", "customer is required");
    14	    }
    15	    if (!Number.isInteger(amountCents) || (amountCents as number) <= 0) {
    16	      throw badRequest("INVALID_REQUEST", "amountCents must be a positive integer");
    17	    }
    18	    return this.orders.insert(customer.trim(), amountCents as number, this.clock().toISOString());
    19	  }
    20	
    21	  get(id: number): Order {
    22	    const order = this.orders.findById(id);
    23	    if (!order) throw notFound("ORDER_NOT_FOUND", `order ${id} not found`);
    24	    return order;
    25	  }
    26	
    27	  list(): Order[] {
    28	    return this.orders.list();
    29	  }
    30	
    31	  pay(id: number): Order {
    32	    const order = this.get(id);
    33	    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
    34	    this.orders.updateStatus(id, "PAID");
    35	    return this.get(id);
    36	  }
    37	
    38	  cancel(id: number): Order {
    39	    const order = this.get(id);
    40	    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
    41	    this.orders.updateStatus(id, "CANCELLED");
    42	    return this.get(id);
    43	  }
    44	}
