applyCoupon:
```ts
applyCoupon(id: number, couponCode: unknown): Order {
  if (typeof couponCode !== "string" || couponCode.trim() === "") {
    throw badRequest("INVALID_REQUEST", "couponCode is required");
  }
  const code = couponCode.trim();
  const order = this.orders.findById(id);
  if (!order) throw notFound("ORDER_NOT_FOUND", `order ${id} not found`);
  if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
  if (order.couponCode !== null) throw conflict("ORDER_ALREADY_HAS_COUPON", `order ${id} already has coupon ${order.couponCode}`);
  const coupon = this.coupons.findByCode(code);
  if (!coupon) throw notFound("COUPON_NOT_FOUND", `coupon ${code} not found`);
  if (coupon.status !== "ACTIVE") throw conflict("COUPON_DISABLED", `coupon ${code} is ${coupon.status}`);
  const now = this.clock();
  if (now.getTime() < Date.parse(coupon.validFrom)) throw conflict("COUPON_NOT_YET_VALID", `coupon ${code} is not valid yet`);
  if (now.getTime() > Date.parse(coupon.validUntil)) throw conflict("COUPON_EXPIRED", `coupon ${code} has expired`);
  if (order.amountCents < coupon.minAmountCents) throw conflict("COUPON_MIN_AMOUNT_NOT_MET", `order amount ${order.amountCents} is below coupon minimum ${coupon.minAmountCents}`);
  if (coupon.usageLimit !== null && coupon.usedCount >= coupon.usageLimit) throw conflict("COUPON_USAGE_LIMIT_REACHED", `coupon ${code} has reached its usage limit`);

  let discount = coupon.type === "FIXED"
    ? coupon.value
    : Math.floor((order.amountCents * coupon.value) / 100);
  if (coupon.maxDiscountCents !== null) discount = Math.min(discount, coupon.maxDiscountCents);
  discount = Math.min(discount, order.amountCents);
  discount = Math.max(0, discount);
  const finalAmount = order.amountCents - discount;

  this.orders.applyCoupon(id, code, discount, finalAmount, now.toISOString());
  return this.get(id);
}
```

