import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");

const OPEN = { validFrom: "2026-01-01T00:00:00Z", validUntil: "2027-01-01T00:00:00Z" };

function setup(): App {
  return createApp({ clock: fixedClock });
}

function newOrder(app: App, amountCents: number): number {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  expect(res.status).toBe(201);
  return (res.body as { id: number }).id;
}

function newCoupon(app: App, overrides: Record<string, unknown> = {}): void {
  const res = app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    ...OPEN,
    ...overrides,
  });
  expect(res.status).toBe(201);
}

const errorCode = (res: { body: unknown }) => (res.body as any).error.code;

describe("apply coupon — discount math", () => {
  it("applies a fixed discount", () => {
    const app = setup();
    newCoupon(app, { code: "FLAT500", type: "FIXED", value: 500 });
    const id = newOrder(app, 12000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "FLAT500" });

    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      id,
      amountCents: 12000,
      discountCents: 500,
      finalAmountCents: 11500,
      couponCode: "FLAT500",
      status: "PENDING",
    });
  });

  it("floors a percentage discount", () => {
    const app = setup();
    newCoupon(app, { code: "P20", type: "PERCENT", value: 20 });
    const id = newOrder(app, 999);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "P20" });

    expect(res.body).toMatchObject({ discountCents: 199, finalAmountCents: 800 });
  });

  it("honours maxDiscountCents", () => {
    const app = setup();
    newCoupon(app, { code: "HALF", type: "PERCENT", value: 50, maxDiscountCents: 1000 });
    const id = newOrder(app, 10000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "HALF" });

    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 9000 });
  });

  it("never discounts below zero", () => {
    const app = setup();
    newCoupon(app, { code: "BIG", type: "FIXED", value: 5000 });
    const id = newOrder(app, 3000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "BIG" });

    expect(res.body).toMatchObject({ discountCents: 3000, finalAmountCents: 0 });
  });
});

describe("apply coupon — redemption tracking", () => {
  it("increments usedCount and writes a redemption row", () => {
    const app = setup();
    newCoupon(app, { code: "P20", type: "PERCENT", value: 20 });
    const id = newOrder(app, 10000);

    app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "P20" });

    expect(app.request("GET", "/coupons/P20").body).toMatchObject({ usedCount: 1 });

    const rows = app.db
      .prepare("SELECT order_id, coupon_code, discount_cents FROM coupon_redemptions")
      .all() as Array<{ order_id: number; coupon_code: string; discount_cents: number }>;
    expect(rows).toEqual([{ order_id: id, coupon_code: "P20", discount_cents: 2000 }]);
  });

  it("leaves no side effects when a rule rejects the request", () => {
    const app = setup();
    newCoupon(app, { code: "MIN", type: "FIXED", value: 100, minAmountCents: 2000 });
    const id = newOrder(app, 1000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "MIN" });

    expect(res.status).toBe(409);
    expect(errorCode(res)).toBe("COUPON_MIN_AMOUNT_NOT_MET");
    expect(app.request("GET", "/coupons/MIN").body).toMatchObject({ usedCount: 0 });
    expect(app.request("GET", `/orders/${id}`).body).toMatchObject({
      discountCents: 0,
      finalAmountCents: 1000,
      couponCode: null,
    });
    expect(app.db.prepare("SELECT COUNT(*) AS n FROM coupon_redemptions").get()).toEqual({ n: 0 });
  });
});

describe("apply coupon — rejections", () => {
  it("rejects a missing couponCode", () => {
    const app = setup();
    const id = newOrder(app, 1000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, {});

    expect(res.status).toBe(400);
    expect(errorCode(res)).toBe("INVALID_REQUEST");
  });

  it("returns 404 for an unknown order", () => {
    const app = setup();
    newCoupon(app, { code: "P20" });

    const res = app.request("POST", "/orders/99/apply-coupon", { couponCode: "P20" });

    expect(res.status).toBe(404);
    expect(errorCode(res)).toBe("ORDER_NOT_FOUND");
  });

  it("returns 404 for an unknown coupon", () => {
    const app = setup();
    const id = newOrder(app, 1000);

    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "NOPE" });

    expect(res.status).toBe(404);
    expect(errorCode(res)).toBe("COUPON_NOT_FOUND");
  });

  it("rejects a non-pending order", () => {
    const app = setup();
    newCoupon(app, { code: "P20" });
